COMMENT ON COLUMN workforce.job_posting.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN workforce.job_posting.job_posting_identifier IS 'Unique identifier of the job posting';
COMMENT ON COLUMN workforce.job_posting.job_organization_identifier IS 'Unique identifier for the organization with the job opening';
