COMMENT ON COLUMN workforce.job_posting.job_description IS 'The description of the job posting';
COMMENT ON COLUMN workforce.job_posting.work_hours IS 'Typical working hours for this job; e.g. "1st shift", "night shift", "8am-5pm"';
COMMENT ON COLUMN workforce.job_posting.job_qualifications IS 'Summary description of the ideal candidate''s qualifications for a position';
COMMENT ON COLUMN workforce.job_posting.job_posting_language IS 'The language of the content of the job posting';
COMMENT ON COLUMN workforce.job_posting.job_location_types IS 'A description of the job location (e.g. TELECOMMUTE for telecommute jobs)';
