COMMENT ON COLUMN workforce.job_posting.pay_minimum IS 'The minimum pay for the job';
COMMENT ON COLUMN workforce.job_posting.pay_maximum IS 'The maximum pay for the job';
COMMENT ON COLUMN workforce.job_posting.pay_average IS 'The average pay for the job';
COMMENT ON COLUMN workforce.job_posting.incentive_compensation IS 'Description of bonus and commission compensation aspects of the job';
COMMENT ON COLUMN workforce.job_posting.citizenship_requirements IS 'Required country of the applicant''s citizenship';
COMMENT ON COLUMN workforce.job_posting.security_clearance_requirements IS 'Description of any security clearance requirements';
COMMENT ON COLUMN workforce.job_posting.travel_requirements IS 'Information about any required travel, systematic or occasional';
COMMENT ON COLUMN workforce.job_posting.work_languages IS 'Information on the work languages used for the job';
COMMENT ON COLUMN workforce.job_posting.job_terms IS 'Type of employment term (e.g. "regular", "temporary", "seasonal"); select from an existing enumeration of such types. Note(s): Use a value selected from a controlled vocabulary of employment term types; select from an existing enumeration of such types.';
COMMENT ON COLUMN workforce.job_posting.job_posted_date IS 'Date on which the position was created';
