COMMENT ON COLUMN workforce.job_posting.technologies IS 'Tool, application or other form of technology that requires knowledge, skill and ability to use effectively in executing the tasks and responsibilities of the job; select from an existing enumeration of such types';
COMMENT ON COLUMN workforce.job_posting.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN workforce.job_posting.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN workforce.job_posting.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN workforce.job_posting.source_system_deleted_date IS 'Date the record was deleted from the source system';
