-- PersonEmployment
-- A tenant-scoped record of current or prior employment, self-employment, military service, or
-- comparable work experience reported for a person.
CREATE TABLE workforce.person_employment (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    person_employment_identifier                     TEXT NOT NULL,
    employer_organization_identifier                 TEXT,
    source_system_identifier                         TEXT,
    description                                      TEXT,
    start_date                                       DATE,
    end_date                                         DATE,
    naics_code                                       TEXT,
    employed_while_enrolled_indicator                BOOLEAN NOT NULL DEFAULT FALSE,
    employment_status_while_enrolled                 TEXT,
    employment_status_work_study_paid_indicator      BOOLEAN,
    employment_status_work_study_unpaid_indicator    BOOLEAN,
    employment_status_soc_code                       TEXT,
    type                                             TEXT,
    role                                             TEXT,
    role_specialization                              TEXT,
    employer_name                                    TEXT,
    employed_after_exit_indicator                    BOOLEAN NOT NULL DEFAULT FALSE,
    employed_prior_to_enrollment_indicator           BOOLEAN NOT NULL DEFAULT FALSE,
    military_enlistment_after_exit_indicator         BOOLEAN NOT NULL DEFAULT FALSE,
    career_pathways_program_participation_indicator  BOOLEAN NOT NULL DEFAULT FALSE,
    separation_reason                                TEXT,
    separation_type                                  TEXT,
    location                                         TEXT,
    contract_type                                    TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_employment PRIMARY KEY (tenant_identifier, person_employment_identifier)
);
COMMENT ON TABLE workforce.person_employment IS 'A tenant-scoped record of current or prior employment, self-employment, military service, or comparable work experience reported for a person.';
COMMENT ON COLUMN workforce.person_employment.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN workforce.person_employment.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN workforce.person_employment.person_employment_identifier IS 'Unique identifier for a person employment record';
COMMENT ON COLUMN workforce.person_employment.employer_organization_identifier IS 'A unique number or alphanumeric code assigned to a school, school system, a state, business, or other agency or entity';
COMMENT ON COLUMN workforce.person_employment.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN workforce.person_employment.description IS 'Description of the responsibilities and accomplishments of the person in this employment';
COMMENT ON COLUMN workforce.person_employment.start_date IS 'The year, month and day on which a person began self-employment or employment with an organization or institution';
COMMENT ON COLUMN workforce.person_employment.end_date IS 'The year, month and day on which a person ended self-employment or employment with an organization or institution';
COMMENT ON COLUMN workforce.person_employment.naics_code IS 'The North American Industry Classification System (NAICS) code associated with an individual''s employment';
COMMENT ON COLUMN workforce.person_employment.employed_while_enrolled_indicator IS 'An individual who is a paid employee or works in his or her own business, profession, or farm, as reported through the State Unemployment Insurance Wage Report, FEDES, or WRIS, and at the same time is enrolled in secondary, postsecondary, or adult education or workforce programs';
COMMENT ON COLUMN workforce.person_employment.employment_status_while_enrolled IS 'An indication of the individual''s employment status while enrolled';
COMMENT ON COLUMN workforce.person_employment.employment_status_work_study_paid_indicator IS 'Indicates whether the individual is taking part in a paid work study for financial aid';
COMMENT ON COLUMN workforce.person_employment.employment_status_work_study_unpaid_indicator IS 'Indicates whether the individual is taking part in an unpaid work study for financial aid';
COMMENT ON COLUMN workforce.person_employment.employment_status_soc_code IS 'SOCCode associated with the learner''s employment';
COMMENT ON COLUMN workforce.person_employment.type IS 'Type of employment (e.g. Volunteer, FullTime)';
COMMENT ON COLUMN workforce.person_employment.role IS 'Role or job title during the person''s employment';
COMMENT ON COLUMN workforce.person_employment.role_specialization IS 'Specialization within the role of the person during their employment';
COMMENT ON COLUMN workforce.person_employment.employer_name IS 'The name of the specific organization for which the person held positions or performed work';
COMMENT ON COLUMN workforce.person_employment.employed_after_exit_indicator IS 'An individual who is a paid employee or works in his or her own business, profession, or farm, as reported through the State Unemployment Insurance Wage Report, FEDES, or WRIS, after exiting secondary, postsecondary, or adult education or workforce programs';
COMMENT ON COLUMN workforce.person_employment.employed_prior_to_enrollment_indicator IS 'An individual who is a paid employee or works in his or her own business, profession, or farm, as reported through the State Unemployment Insurance Wage Report, FEDES, or WRIS, before enrolling in secondary, postsecondary, or adult education or workforce programs';
COMMENT ON COLUMN workforce.person_employment.military_enlistment_after_exit_indicator IS 'An individual who is a member of the uniformed armed forces of the United States as reported through FEDES after exiting secondary, postsecondary, or adult education or workforce programs';
COMMENT ON COLUMN workforce.person_employment.career_pathways_program_participation_indicator IS 'An indication of an individual who is participating in a program that is a component of or leads to a specific or recognized career pathway, as defined by the state';
COMMENT ON COLUMN workforce.person_employment.separation_reason IS 'The primary reason for the termination of the employment relationship';
COMMENT ON COLUMN workforce.person_employment.separation_type IS 'A designation of the type of separation occurring between a person and the organization';
COMMENT ON COLUMN workforce.person_employment.location IS 'Location where experience obtained';
COMMENT ON COLUMN workforce.person_employment.contract_type IS 'The type of employment contract used by an institution';
COMMENT ON COLUMN workforce.person_employment.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN workforce.person_employment.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN workforce.person_employment.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN workforce.person_employment.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN workforce.person_employment.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN workforce.person_employment.created_date IS 'Date and time record was created';
COMMENT ON COLUMN workforce.person_employment.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN workforce.person_employment.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN workforce.person_employment.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN workforce.person_employment.deleted_date IS 'Date and time record was deleted';

